function makeRectRing(cx: number, cz: number, w: number, d: number): Array<[number, number]> {
  const hw = w / 2;
  const hd = d / 2;
  return [
    [cx - hw, cz - hd],
    [cx + hw, cz - hd],
    [cx + hw, cz + hd],
    [cx - hw, cz + hd],
  ];
}

